/* Portable backup format. No credentials, sessions or server secrets are serialized. */
const AcervoBackup=(()=>{
 const MAX_BYTES=64*1024*1024,FORMAT='acervo-musical-backup',VERSION=1;
 function canonical(value){if(value===null||typeof value!=='object')return JSON.stringify(value);if(Array.isArray(value))return '['+value.map(canonical).join(',')+']';return '{'+Object.keys(value).sort().map(key=>JSON.stringify(key)+':'+canonical(value[key])).join(',')+'}';}
 async function hash(bytes){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');}
 const digest=value=>hash(new TextEncoder().encode(canonical(value)));
 function encode(bytes){let out='';for(let i=0;i<bytes.length;i+=8192)out+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(out);}
 function decode(value){if(typeof value!=='string'||value.length>Math.ceil(MAX_BYTES/3)*4||(value.length%4!==0||! /^[A-Za-z0-9+/]*={0,2}$/.test(value)))throw Error('Arquivo codificado inválido.');return Uint8Array.from(atob(value),x=>x.charCodeAt(0));}
 function settings(value={}){const result={};for(const [key,item]of Object.entries(value)){if(!['acervo-musical-theme','acervo-musical-favorites','acervo-musical-recent','acervo-musical-reader-mode'].includes(key))throw Error('Configuração não permitida no backup.');if(typeof item!=='string'||item.length>100000)throw Error('Configuração inválida.');if(key==='acervo-musical-theme'&&!['system','light','dark'].includes(item))throw Error('Tema inválido.');if(/favorites|recent/.test(key)){const ids=JSON.parse(item);if(!Array.isArray(ids)||ids.length>1000||ids.some(id=>typeof id!=='string'))throw Error('Preferência inválida.');}if(key.endsWith('reader-mode')&&!['complete','map'].includes(item))throw Error('Modo inválido.');result[key]=item;}return result;}
 function users(value,data){if(!Array.isArray(value)||value.length>1000)throw Error('Usuários inválidos.');const ids=new Set(),names=new Set();return value.map(user=>{if(Object.keys(user).some(key=>!['id','username','role','departmentId'].includes(key)))throw Error('Credenciais ou campos não permitidos no backup.');if(!Number.isSafeInteger(user.id)||user.id===0||ids.has(user.id)||typeof user.username!=='string'||!user.username||user.username.length>254||names.has(user.username)||!['admin','member','department_admin'].includes(user.role))throw Error('Usuário inválido.');if(user.role==='department_admin'&&!data.departments.some(d=>d.id===user.departmentId))throw Error('Departamento de usuário inexistente.');ids.add(user.id);names.add(user.username);return {id:user.id,username:user.username,role:user.role,departmentId:user.departmentId||null};});}
 function ownedReferences(data){const refs=[];for(const song of data.songs){for(const resource of song.resources||[]){const match=String(resource.url||'').match(/\/api\/media\/([a-f0-9-]{36})(?:[?#].*)?$/);if(resource.storage==='local'||resource.storage==='server'||match){const id=resource.fileId||match?.[1];if(!id)throw Error('Referência de arquivo inválida.');refs.push({songId:song.id,resourceId:resource.id,id});}}for(const field of ['scoreLink','gradeLink','pdfLink','audioLink','videoLink','voicesLink','projectionLink']){const match=String(song[field]||'').match(/\/api\/media\/([a-f0-9-]{36})(?:[?#].*)?$/);if(match)refs.push({songId:song.id,field,id:match[1]});}}return refs;}
 async function seal(payload){return {format:FORMAT,version:VERSION,payload,sha256:await digest(payload)};}
 async function verify(backup,validate){if(!backup||backup.format!==FORMAT||backup.version!==VERSION||!backup.payload||await digest(backup.payload)!==backup.sha256)throw Error('Backup inválido ou integridade comprometida.');const p=backup.payload;if(Object.keys(p).some(k=>!['createdAt','source','data','users','settings','files'].includes(k)))throw Error('Campos não permitidos.');if(!['local','server'].includes(p.source)||!Number.isFinite(Date.parse(p.createdAt)))throw Error('Origem ou data inválida.');const data=validate(structuredClone(p.data)),safeUsers=users(p.users,data),safeSettings=settings(p.settings);if(canonical(data)!==canonical(p.data))throw Error('Dados do backup exigem migração não suportada.');if(!Array.isArray(p.files))throw Error('Lista de arquivos inválida.');let total=0;const ids=new Set();for(const file of p.files){if(Object.keys(file).some(k=>!['id','name','type','size','sha256','base64'].includes(k))||typeof file.id!=='string'||!/^[a-z0-9-]{1,100}$/i.test(file.id)||ids.has(file.id)||typeof file.name!=='string'||file.name.length>200||typeof file.type!=='string'||file.type.length>100)throw Error('Metadados de arquivo inválidos.');const bytes=decode(file.base64);total+=bytes.length;if(total>MAX_BYTES||bytes.length!==file.size||await hash(bytes)!==file.sha256)throw Error('Integridade do anexo comprometida ou limite de 64 MB excedido.');ids.add(file.id);}const refs=ownedReferences(data);if(refs.some(ref=>!ids.has(ref.id))||[...ids].some(id=>!refs.some(ref=>ref.id===id)))throw Error('Relacionamentos de arquivos incompletos.');return {...p,data,users:safeUsers,settings:safeSettings};}
 async function make({data,users:accounts=[],settings:preferences={},source,readFile}){const files=[];let total=0;for(const id of new Set(ownedReferences(data).map(ref=>ref.id))){const file=await readFile(id);if(!file)throw Error('Anexo ausente: '+id);const bytes=new Uint8Array(await file.arrayBuffer());total+=bytes.length;if(total>MAX_BYTES)throw Error('Backup excede 64 MB de anexos. Nenhum dado foi alterado.');files.push({id,name:file.name||id+'.bin',type:file.type||'application/octet-stream',size:bytes.length,sha256:await hash(bytes),base64:encode(bytes)});}return seal({createdAt:new Date().toISOString(),source,data:structuredClone(data),users:users(accounts,data),settings:settings(preferences),files});}
 function remap(data,mapping,mode,origin='',files=[]){const next=structuredClone(data),types={scoreLink:'partitura',gradeLink:'cifra',pdfLink:'partitura',audioLink:'vozes',videoLink:'videoaula',voicesLink:'vozes',projectionLink:'projecao'};for(const ref of ownedReferences(next)){const song=next.songs.find(s=>s.id===ref.songId),id=mapping[ref.id];if(!id)throw Error('Anexo não preparado.');if(ref.field&&mode==='server'){song[ref.field]=origin+'/api/media/'+id;continue;}let resource;if(ref.field){song[ref.field]='';resource={id:crypto.randomUUID(),type:types[ref.field],instrument:'Geral',label:files.find(file=>file.id===ref.id)?.name||ref.field};song.resources.push(resource);}else resource=song.resources.find(r=>r.id===ref.resourceId);Object.assign(resource,{storage:mode,fileId:id,url:mode==='local'?'':origin+'/api/media/'+id});}return next;}
 async function restoreLocal({backup,validate,readCurrent,readFile,storeFile,readStored,commit,revision}){const p=await verify(backup,validate),current=await readCurrent();if(current.revision!==revision)throw Error('O acervo mudou. Reabra a importação.');const safety=await make({...current,source:'local',readFile}),safetyId='recovery-'+crypto.randomUUID();await storeFile(safetyId,new Blob([JSON.stringify(safety)],{type:'application/json'}));const stored=await readStored(safetyId);if(!stored)throw Error('Não foi possível preservar o acervo atual.');await verify(JSON.parse(await stored.text()),validate);const mapping={};for(const file of p.files){const id=crypto.randomUUID();await storeFile(id,new File([decode(file.base64)],file.name,{type:file.type}));const saved=await readStored(id);if(!saved||await hash(await saved.arrayBuffer())!==file.sha256)throw Error('Falha ao preparar anexo. Acervo atual preservado.');mapping[file.id]=id;}const latest=await readCurrent();if(latest.revision!==revision)throw Error('O acervo mudou durante a preparação.');const data=validate(remap(p.data,mapping,'local','',p.files));await commit({data,revision:revision+1,backupSettings:p.settings,backupUsers:p.users,recoveryId:safetyId});return {data,safetyId};}
 return {MAX_BYTES,hash,digest,encode,decode,settings,users,ownedReferences,seal,verify,make,remap,restoreLocal};
})();

