async function api(path,options={}){
 if(location.protocol==='file:')return localApi(path,options);
 const response=await fetch(path,{cache:'no-store',...options});let body;try{body=await response.json();}catch{throw Error('Não foi possível conectar ao servidor.');}if(response.status===401){location.href=location.hash.startsWith('#gerenciar')?'/admin/login':'/login';throw Error('Entre novamente.');}if(!response.ok)throw Error(body.error||'Não foi possível concluir.');return body;
}
function localApi(path,options={}){
 if(path==='/api/me')return {user:{id:0,username:'Acesso local',role:'admin'},loginRequired:false};
 if(path!=='/api/data')throw Error('Operação disponível somente pelo servidor.');
 const key='acervo-musical-local-v1';let saved;try{saved=JSON.parse(localStorage.getItem(key)||'null');}catch{throw Error('Não foi possível ler os dados locais.');}
 const current=saved?{data:validate(saved.data),revision:saved.revision}:{data:structuredClone(seed),revision:1};
 if(options.method!=='PUT')return current;
 const next=JSON.parse(options.body),data=validate(next.data);if(next.revision!==current.revision)throw Error('Os dados mudaram em outra janela. Atualize a página antes de salvar.');
 try{storage.write(key,{...saved,data,revision:current.revision+1});}catch{throw Error('Não foi possível salvar neste navegador. Exporte os dados para guardar uma cópia.');}return {ok:true,revision:current.revision+1};
}
async function persist(next){
 if(busy)return false;if(!canManage()){toast('Seu perfil permite apenas consulta no acervo.');return false;}
 busy=true;document.body.classList.add('saving');try{const data=validate(next);const result=await api('/api/data',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({data,revision})});state=data;revision=result.revision;return true;}catch(error){toast(error.message);return false;}finally{busy=false;document.body.classList.remove('saving');}
}
