function loadProjectionSong(){currentSong=projectionQueue[projectionIndex];slides=songLyricText(currentSong).split(/\n\s*\n/).map(value=>value.trim()).filter(Boolean);$('#projection-title').textContent=currentSong.name;drawSlide();}
function drawSlide(){$('#slide-text').textContent=slides[slideIndex];$('#slide-count').textContent=(projectionIndex+1)+'º louvor · '+(slideIndex+1)+' / '+slides.length;$('#previous-slide').disabled=slideIndex===0&&projectionIndex===0;$('#next-slide').disabled=slideIndex===slides.length-1&&projectionIndex===projectionQueue.length-1;}
function moveSlide(direction){if(direction>0){if(slideIndex<slides.length-1)slideIndex++;else if(projectionIndex<projectionQueue.length-1){projectionIndex++;slideIndex=0;loadProjectionSong();}}else if(slideIndex>0)slideIndex--;else if(projectionIndex>0){projectionIndex--;loadProjectionSong();slideIndex=slides.length-1;}drawSlide();}
function exitProjection(){$('#projection').hidden=true;if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});openSong(currentSong.id);}
$('#previous-slide').onclick=()=>moveSlide(-1);$('#next-slide').onclick=()=>moveSlide(1);$('#exit-projection').onclick=exitProjection;$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#projection').requestFullscreen();}catch{toast('Tela cheia indisponível neste navegador.');}};
function toggleMenu(open){if(window.matchMedia?.('(max-width: 1000px)').matches===false){setDesktopSidebarCollapsed(!desktopSidebarCollapsed);return;}const mobile=window.matchMedia?.('(max-width: 1000px)').matches??true;const active=mobile&&open;document.body.classList.toggle('menu-open',active);$('.workspace').inert=active;$('#sidebar').inert=mobile&&!active;$('#menu-toggle').setAttribute('aria-expanded',String(active));$('#menu-backdrop').hidden=!active;syncSidebarControl();if(active)$('nav a').focus();else if(mobile)$('#menu-toggle').focus();}
document.addEventListener('click',async event=>{
 const close=event.target.closest('[data-close]');if(close){if(recording){toast('Aguarde a gravação terminar.');return;}$('#'+close.dataset.close).close();return;}
 const tab=event.target.closest('[data-tab]');if(tab){if(recording)return;currentTab=tab.dataset.tab;detail();$('#tab-'+currentTab).focus();return;}
 const target=event.target.closest('[data-action]');if(!target)return;const id=target.dataset.id;
 switch(target.dataset.action){case 'navigate':location.hash=target.dataset.page;break;case 'song':openSong(id,target.dataset.repertoire==='true'||page==='repertorio');break;case 'close-menu':toggleMenu(false);break;case 'favorite':try{const next=favorites.includes(id)?favorites.filter(value=>value!==id):[...favorites,id];storage.write('acervo-musical-favorites',next);favorites=next;updateLibrary();}catch{toast('Não foi possível guardar os favoritos neste navegador.');}break;case 'edit':edit(target.dataset.kind,id);break;case 'project':project();break;case 'present-repertoire':project(department().repertoire.map(entry=>state.songs.find(song=>song.id===entry.songId)));break;case 'print':window.print();break;case 'add-repertoire':mutateRepertoire('add',$('#repertoire-song').value);break;case 'remove-repertoire':mutateRepertoire('remove',id);break;case 'move-repertoire':mutateRepertoire('move',id,Number(target.dataset.direction));break;case 'select-department':selectDepartment(id);location.hash='louvores';break;case 'delete-department':deleteDepartment(id);break;case 'all-songs':filters.all=true;location.hash='louvores';break;case 'export':exportData();break;case 'import':if(isAdmin())$('#import-file').click();break;case 'toggle-drums':if(recording)return;if(drumTimer){stopDrums();target.textContent='Reproduzir simulação';}else{startDrums();target.textContent='Pausar simulação';}break;case 'record':recordDemo();break;case 'logout':try{await api('/api/logout',{method:'POST'});location.href='/login';}catch(error){toast(error.message);}break;case 'users':manageUsers();break;case 'delete-song':deleteSong(id);break;}
});
document.addEventListener('change',async event=>{const id=event.target.dataset.entryKey||event.target.dataset.entryNotes;if(!id)return;const next=structuredClone(state),entry=next.departments.find(d=>d.id===departmentId).repertoire.find(item=>item.songId===id);if(!entry)return;if(event.target.dataset.entryKey)entry.key=event.target.value;else entry.notes=event.target.value;if(await persist(next))toast('Observação e tom salvos.');});
document.addEventListener('keydown',event=>{if(!$('#projection').hidden){if(['ArrowRight','ArrowLeft'].includes(event.key)){event.preventDefault();moveSlide(event.key==='ArrowRight'?1:-1);}if(event.key==='Escape')exitProjection();return;}if(document.body.classList.contains('menu-open')){if(event.key==='Escape')toggleMenu(false);if(event.key==='Tab'){const links=$$('#sidebar a,#sidebar button').filter(element=>!element.hidden),first=links[0],last=links[links.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}}if(event.target.matches('[role="tab"]')&&['ArrowRight','ArrowLeft','Home','End'].includes(event.key)){event.preventDefault();const tabs=Object.keys(tabLabels),index=tabs.indexOf(currentTab);currentTab=tabs[event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length];detail();$('#tab-'+currentTab).focus();}});
