async function deleteSong(id){if(!isAdmin())return;const song=state.songs.find(s=>s.id===id);if(!song||!confirm('Excluir '+song.name+' do acervo e de todos os repertórios? Os arquivos externos serão preservados.'))return;const next=structuredClone(state);next.songs=next.songs.filter(s=>s.id!==id);next.departments.forEach(d=>d.repertoire=d.repertoire.filter(e=>e.songId!==id));if(await persist(next)){$('#detail').close();render();toast('Louvor excluído.');}}
async function manageUsers(){if(!isAdmin())return;try{const result=await api('/api/users');let dialog=$('#users-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='users-dialog';document.body.append(dialog);}dialog.innerHTML='<div class="dialog-head"><h2>Equipe e permissões</h2><button class="button secondary" data-close="users-dialog" aria-label="Voltar">← Voltar</button></div><div class="tab-content"><p class="form-hint">Acompanhe quantas músicas cada conta cadastrou. O limite de referência para uma futura cobrança é 20; nenhuma cobrança é feita pelo aplicativo hoje.</p>'+result.users.map(user=>'<div class="user-row"><div><strong>'+esc(user.username)+'</strong><small>'+esc({admin:'Administrador',department_admin:'Consulta (perfil antigo)',member:'Músico'}[user.role])+'</small></div><span>'+Number(user.songCount||0)+' '+(user.songCount===1?'música':'músicas')+(user.billingEligible?' · acima de 20':'')+'</span></div>').join('')+'<form class="account-form" id="account-form"><label>Usuário<input name="username" minlength="3" maxlength="40" pattern="[a-zA-Z0-9._-]+" required></label><label>Senha inicial<input name="password" type="password" minlength="4" maxlength="128" autocomplete="new-password" required></label><label>Perfil<select name="role"><option value="member">Músico</option><option value="admin">Administrador geral</option></select></label><button class="button" type="submit">Cadastrar usuário</button></form></div>';dialog.showModal();$('#account-form').onsubmit=async event=>{event.preventDefault();const submit=event.target.querySelector('button');submit.disabled=true;try{await api('/api/users',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});dialog.close();toast('Usuário cadastrado.');}catch(error){toast(error.message);}finally{submit.disabled=false;}};}catch(error){toast(error.message);}}

