function confirmSongTextChanges(id,values){const original=state.songs.find(song=>song.id===id);if((original?.chords||'')===(values.chords||'')&&(original?.lyrics||'')===(values.lyrics||''))return true;return confirm('Salvar as alterações da letra/cifra nesta música? A versão do formulário substituirá esses campos. O tom original e os demais materiais serão preservados.');}
function chordChoiceMarkup(){const notes=ChordEditorModel.notes.map(note=>'<option>'+note+'</option>').join('');return '<fieldset class="chord-choice"><legend>Escolha o acorde</legend><div class="chord-choice-fields"><label>Nota<select id="chord-root">'+notes+'</select></label><label>Tipo<select id="chord-quality">'+ChordEditorModel.qualities.map(([value,label])=>'<option value="'+value+'">'+label+'</option>').join('')+'<option value="custom">Personalizado</option></select></label><label>Baixo<select id="chord-bass"><option value="">Sem inversão</option>'+notes+'</select></label></div><div class="chord-quick-choices" role="group" aria-label="Acordes frequentes">'+['C','D','E','F','G','A','B','Am','Dm','Em','Bm','F#m'].map(chord=>button(chord,'chord-editor-pick','data-chord="'+chord+'" aria-label="Escolher acorde '+chord+'"',true)).join('')+'</div></fieldset>';}
function updateChordPosition(){const session=chordEditorSession;if(!session)return;const area=$('#chord-visual-text'),selected=ChordEditorModel.selection(session.model,area.selectionStart||0,area.selectionEnd??(area.selectionStart||0));session.selection=selected;$('#chord-position-info').textContent='Linha '+selected.line+', posição '+selected.column+(selected.text?' · '+(selected.end>selected.start?'Seleção: ':'Trecho: ')+selected.text.replace(/\n/g,' ↵ '):' · Fim da letra');}
function syncChordChoice(chord){const normalized=chord.replace(/♯/g,'#').replace(/♭/g,'b'),match=normalized.match(/^([A-G][#b]?)(.*?)(?:\/([A-G][#b]?))?$/);if(!match)return;$('#chord-root').value=match[1];$('#chord-quality').value=ChordEditorModel.qualities.some(([value])=>value===match[2])?match[2]:'custom';$('#chord-bass').value=match[3]||'';}
function chooseChordFromControls(){if(!chordEditorSession||$('#chord-quality').value==='custom')return;$('#chord-input').value=ChordEditorModel.chordFromChoice($('#chord-root').value,$('#chord-quality').value,$('#chord-bass').value);updateChordPosition();}
function openChordEditor(){if(!isAdmin()||editTarget?.kind!=='songs')return;const source=$('#editor').querySelector('[name="chords"]'),lyrics=$('#editor').querySelector('[name="lyrics"]');if(!source)return;let dialog=$('#chord-editor');if(!dialog){dialog=document.createElement('dialog');dialog.id='chord-editor';dialog.className='chord-editor';dialog.setAttribute('aria-labelledby','chord-editor-title');document.body.append(dialog);}
 const initial=source.value;chordEditorSession={initial,source:initial,model:ChordEditorModel.project(initial),parent:source,lyrics:lyrics?.value||'',mode:ChordEditorModel.legacy(initial)?'source':'visual',history:[],selected:null};
 dialog.innerHTML='<div class="dialog-head"><div><h2 id="chord-editor-title">Editor de cifras e letras</h2><p class="form-hint">O cadastro só muda depois de aplicar e salvar o formulário.</p></div>'+button('Voltar','chord-editor-close','',true)+'</div><div class="chord-editor-toolbar"><div role="group" aria-label="Modo de edição">'+button('Visual','chord-editor-mode','data-mode="visual" aria-pressed="true"',true)+button('ChordPro','chord-editor-mode','data-mode="source" aria-pressed="false"',true)+'</div>'+button('Usar letra cadastrada','chord-editor-lyrics','',true)+button('Desfazer','chord-editor-undo','',true)+button('Restaurar rascunho inicial','chord-editor-reset','',true)+'</div><div class="chord-editor-workspace"><section class="chord-editor-input"><div id="chord-visual-panel"><label for="chord-visual-text">Letra — clique na posição exata para inserir um acorde</label><p id="chord-position-info" class="chord-position-info" role="status" aria-live="polite"></p><textarea id="chord-visual-text" aria-describedby="chord-position-info" rows="13" maxlength="20000" spellcheck="false"></textarea>'+chordChoiceMarkup()+'<div class="chord-insert-controls"><label>Acorde escolhido / personalizado<input id="chord-input" maxlength="128" placeholder="Ex.: C7(b9) ou D/F#" autocomplete="off"></label>'+button('Inserir na posição','chord-editor-insert','',true)+'</div><label>Acordes inseridos<select id="chord-anchor"><option value="">Selecione um acorde</option></select></label><div class="actions">'+button('Alterar acorde','chord-editor-update','data-requires-anchor',true)+button('Remover','chord-editor-remove','data-requires-anchor',true)+button('Mover para o cursor','chord-editor-move','data-requires-anchor',true)+'</div>'+sectionEditorMarkup()+'<p class="form-hint">Selecione um acorde na lista para alterar ou remover. Para mover, selecione-o, clique na nova posição da letra e use Mover para o cursor.</p></div><div id="chord-source-panel" hidden><label for="chord-source-text">Cole ou edite ChordPro</label><textarea id="chord-source-text" rows="19" maxlength="20000" spellcheck="false"></textarea><p class="form-hint">Exemplo: [C]Eu quero [G]estar em Tua presença. Diretivas e metadados são preservados.</p><label>Importar arquivo ChordPro ou texto<input id="chord-source-file" type="file" accept=".cho,.chopro,.chordpro,.pro,.txt,text/plain"></label></div><p id="chord-editor-status" role="status" aria-live="polite"></p></section><section class="chord-editor-preview" aria-label="Pré-visualização da cifra"><div class="chord-preview-heading"><h3>Pré-visualização</h3><label>Largura<select id="chord-preview-width"><option value="100%">Automática</option><option value="320px">Celular · 320 px</option><option value="768px">Tablet · 768 px</option><option value="1100px">Computador</option></select></label></div><div id="chord-preview" class="chord-sheet"></div><div id="chord-editor-warnings" class="form-hint" role="status"></div></section></div><div class="form-actions">'+button('Cancelar','chord-editor-close','',true)+button('Usar esta cifra no formulário','chord-editor-apply')+'</div>';dialog.oncancel=event=>{if(chordEditorSession?.source!==chordEditorSession?.initial&&!confirm('Descartar as alterações deste rascunho?'))event.preventDefault();};dialog.addEventListener('close',()=>{chordEditorSession=null;},{once:true});dialog.showModal();renderChordEditor(true);
 $('#chord-input').value='C';$('#chord-root').value='C';$('#chord-quality').value='';$('#chord-bass').value='';
 $('#chord-section-list').onchange=()=>{chordEditorSession.sectionId=$('#chord-section-list').value;renderSectionEditor();};
 for(const name of ['chord-root','chord-quality','chord-bass'])$('#'+name).onchange=chooseChordFromControls;
 $('#chord-input').oninput=event=>syncChordChoice(event.target.value);
 for(const type of ['onclick','onselect','onkeyup'])$('#chord-visual-text')[type]=updateChordPosition;
 updateChordPosition();
 $('#chord-visual-text').oninput=event=>{try{const session=chordEditorSession,result=ChordEditorModel.replaceText(session.model,event.target.value);setChordDraft(ChordEditorModel.serialize(result.model),result.model,false);updateChordPosition();if(result.removed)$('#chord-editor-status').textContent=result.removed+' acordes removidos junto com o trecho apagado. Confira a prévia.';}catch(error){$('#chord-editor-status').textContent=error.message;}};
 $('#chord-source-text').oninput=event=>{try{setChordDraft(event.target.value,null,false);}catch(error){$('#chord-editor-status').textContent=error.message;}};
 $('#chord-anchor').onchange=event=>{const session=chordEditorSession;session.selected=event.target.value||null;const anchor=session.model.anchors.find(item=>item.id===session.selected);if(anchor){$('#chord-input').value=anchor.chord;syncChordChoice(anchor.chord);const area=$('#chord-visual-text');area.focus();area.setSelectionRange(anchor.offset,anchor.offset);updateChordPosition();}
 $$('#chord-editor [data-requires-anchor]').forEach(control=>control.disabled=!anchor);};
 $('#chord-preview-width').onchange=event=>{$('#chord-preview').style.width=event.target.value;};
 $('#chord-source-file').onchange=async event=>{try{const session=chordEditorSession,file=event.target.files?.[0];if(!file||!session)return;if(file.size>80000)throw Error('Use um arquivo de até 80 KB e 20.000 caracteres.');const text=await file.text();if(chordEditorSession!==session)return;ChordEditorModel.check(text);if(chordEditorSession.source&&!confirm('Substituir o rascunho pelo texto deste arquivo? O cadastro ainda não será alterado.'))return;setChordDraft(text);}catch(error){$('#chord-editor-status').textContent=error.message;}finally{event.target.value='';}};
}
function setChordDraft(source,model=null,refreshInput=true){const session=chordEditorSession;if(!session)return;ChordEditorModel.check(source);if(source!==session.source){session.history.push(session.source);session.history=session.history.slice(-20);}session.source=source;session.model=model||ChordEditorModel.project(source);session.selected=null;renderChordEditor(refreshInput);}
function renderChordEditor(refreshInput=false){const session=chordEditorSession;if(!session)return;$('#chord-visual-panel').hidden=session.mode!=='visual';$('#chord-source-panel').hidden=session.mode!=='source';if(refreshInput){$('#chord-source-text').value=session.source;$('#chord-visual-text').value=session.model.text;}else if(session.mode==='visual')$('#chord-source-text').value=session.source;else $('#chord-visual-text').value=session.model.text;renderSectionEditor();const parsed=ChordSheet.parse(session.source);$('#chord-preview').innerHTML=ChordSheet.render(ChordSheet.transposed(parsed,0),esc);$('#chord-editor-warnings').textContent=(parsed.warnings||[]).join(' ');$('#chord-anchor').innerHTML='<option value="">Selecione um acorde</option>'+session.model.anchors.map(anchor=>'<option value="'+anchor.id+'">'+esc(anchor.chord+' · '+session.model.text.slice(Math.max(0,anchor.offset-8),anchor.offset+25).replace(/\n/g,' ↵ '))+'</option>').join('');$('#chord-anchor').value=session.selected||'';$$('#chord-editor [data-requires-anchor]').forEach(control=>control.disabled=!session.selected);$$('#chord-editor [data-action="chord-editor-mode"]').forEach(control=>control.setAttribute('aria-pressed',String(control.dataset.mode===session.mode)));$('#chord-editor-status').textContent=session.model.anchors.length+' acordes posicionados. '+session.model.extras.length+' diretivas/comentários preservados.';}
function chordEditorAction(action,target){const session=chordEditorSession;if(!session)return;try{const area=$('#chord-visual-text'),offset=ChordEditorModel.selection(session.model,area.selectionStart||0).start;if(action==='chord-editor-pick'){const chord=target.dataset.chord;if(!MusicTranspose.isChord(chord))return;$('#chord-input').value=chord;syncChordChoice(chord);updateChordPosition();return;}if(action==='chord-editor-close'){if(session.source!==session.initial&&!confirm('Descartar as alterações deste rascunho?'))return;$('#chord-editor').close();return;}if(action==='chord-editor-apply'){ChordEditorModel.check(session.source);session.parent.value=session.source;$('#chord-editor').close();toast('Cifra aplicada ao formulário. Confira e use Salvar alterações.');return;}if(action==='chord-editor-mode'){const mode=target.dataset.mode;if(!['source','visual'].includes(mode))return;if(mode==='visual'&&ChordEditorModel.legacy(session.source)){if(!confirm('Preparar os acordes tradicionais usando as posições já existentes? Confira a conversão antes de salvar.'))return;setChordDraft(ChordEditorModel.convertLegacy(session.source));}session.mode=mode;renderChordEditor(true);return;}if(action==='chord-editor-lyrics'){if(!session.lyrics){toast('Não há letra separada cadastrada neste formulário.');return;}if(session.source&&!confirm((SongSections.scan(session.source).sections.length?'As se\u00e7\u00f5es atuais ser\u00e3o mantidas e a letra ser\u00e1 acrescentada ao final, sem posicionar acordes automaticamente. Continuar?':'Usar a letra separada como base deste rascunho? Os acordes atuais não serão copiados nem posicionados automaticamente.')))return;setChordDraft(SongSections.importLyrics(session.source,session.lyrics));session.mode='visual';renderChordEditor(true);return;}if(action==='chord-editor-reset'){if(!confirm('Restaurar o rascunho inicial?'))return;setChordDraft(session.initial);return;}if(action==='chord-editor-undo'){const previous=session.history.pop();if(previous===undefined)return;session.source=previous;session.model=ChordEditorModel.project(previous);session.selected=null;renderChordEditor(true);return;}if(action.startsWith('chord-editor-section')){sectionEditorAction(action,offset);return;}let model;if(action==='chord-editor-insert')model=ChordEditorModel.putChord(session.model,$('#chord-input').value.trim(),offset);if(action==='chord-editor-update')model=ChordEditorModel.putChord(session.model,$('#chord-input').value.trim(),offset,session.selected||'missing');if(action==='chord-editor-remove')model=ChordEditorModel.removeChord(session.model,session.selected);if(action==='chord-editor-move')model=ChordEditorModel.moveChord(session.model,session.selected,offset);if(model){const oldSelected=session.selected,inserted=action==='chord-editor-insert'?model.anchors.find(anchor=>!session.model.anchors.some(old=>old.id===anchor.id)):null;setChordDraft(ChordEditorModel.serialize(model),model);session.selected=inserted?.id||(model.anchors.some(anchor=>anchor.id===oldSelected)?oldSelected:null);renderChordEditor(false);area.focus();area.setSelectionRange(offset,offset);updateChordPosition();}}catch(error){$('#chord-editor-status').textContent=error.message;}}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;if(['song-chord-editor','lyrics-chord-editor'].includes(action)){if(!isAdmin())return;const id=target.dataset.id;if(typeof recording!=='undefined'&&recording)return;edit('songs',id);if(!$('#editor').open||editTarget?.kind!=='songs'||editTarget.id!==id)return;openChordEditor();if(action==='lyrics-chord-editor')chordEditorAction('chord-editor-lyrics',{});}else if(action==='chord-editor-open')openChordEditor();else if(action?.startsWith('chord-editor-'))chordEditorAction(action,target);});

/* Section controls only change the existing editor draft. */
function sectionEditorMarkup(){return '<fieldset class="section-editor"><legend>Seções musicais</legend><div class="chord-section-controls"><label>Nova seção<select id="chord-section">'+SongSections.types.map(label=>'<option>'+esc(label)+'</option>').join('')+'</select></label><label>Posição<select id="chord-section-position"><option value="cursor">Linha do cursor</option><option value="before">Antes da seção selecionada</option><option value="after">Depois da seção selecionada</option></select></label>'+button('Inserir seção','chord-editor-section','',true)+'</div><label>Seções na ordem da música<select id="chord-section-list" aria-describedby="chord-section-help"></select></label><div class="chord-section-controls"><label>Nome da seção<input id="chord-section-name" maxlength="80" autocomplete="off"></label>'+button('Renomear','chord-editor-section-rename','data-requires-section',true)+'</div><div class="actions">'+button('Mover acima','chord-editor-section-up','data-requires-section',true)+button('Mover abaixo','chord-editor-section-down','data-requires-section',true)+'</div><p id="chord-section-help" class="form-hint">Cada seção leva sua letra e seus acordes ao mudar de posição. As alterações ficam no rascunho até salvar.</p><p id="chord-section-status" class="form-hint" role="status"></p></fieldset>';}
function renderSectionEditor(){const session=chordEditorSession,document=SongSections.scan(session.source);const selected=document.sections.find(item=>item.id===session.sectionId)||document.sections[Math.min(session.sectionIndex||0,document.sections.length-1)];session.sectionId=selected?.id||null;session.sectionIndex=selected?.index||0;$('#chord-section-list').innerHTML=document.sections.map(section=>'<option value="'+section.id+'">'+(section.index+1)+'. '+esc(section.label)+'</option>').join('')||'<option value="">Nenhuma seção identificada</option>';$('#chord-section-list').value=session.sectionId||'';$('#chord-section-name').value=selected?.label||'';$$('#chord-editor [data-requires-section]').forEach(control=>control.disabled=!selected||(control.dataset.action==='chord-editor-section-up'&&selected.index===0)||(control.dataset.action==='chord-editor-section-down'&&selected.index===document.sections.length-1));$('#chord-section-status').textContent=document.warnings.join(' ')+(document.dependent?' Repetições de refrão ou transposição global: revise a ordem no modo ChordPro.':'');}
function sectionEditorAction(action,offset){const session=chordEditorSession,document=SongSections.scan(session.source),selected=document.sections.find(item=>item.id===session.sectionId);let next;
 if(action==='chord-editor-section'){const placement=$('#chord-section-position').value;let point=ChordEditorModel.sourceOffset(session.model,offset);if(placement==='before'||placement==='after'){if(!selected)throw Error('Selecione uma seção para definir a posição.');point=placement==='before'?selected.start:selected.end;}next=SongSections.insert(session.source,point,$('#chord-section').value);}
 else{if(!selected)throw Error('Selecione uma seção.');if(action==='chord-editor-section-rename')next=SongSections.rename(session.source,selected.id,$('#chord-section-name').value);else if(action==='chord-editor-section-up'||action==='chord-editor-section-down'){const direction=action==='chord-editor-section-up'?-1:1;next=SongSections.move(session.source,selected.id,direction);if(next!==session.source){session.sectionIndex=selected.index+direction;session.sectionId=null;}}}
 if(next!==undefined)setChordDraft(next);
}

class CifraAutoScroll{
 constructor({frame=fn=>requestAnimationFrame(fn),cancel=id=>cancelAnimationFrame(id),reduced=()=>false,onState=()=>{}}={}){this.frame=frame;this.cancel=cancel;this.reduced=reduced;this.onState=onState;this.speed=24;this.running=false;this.id=null;this.element=null;this.previous=null;this.tick=this.tick.bind(this);}
 setSpeed(value){const speed=Number(value);if(Number.isFinite(speed))this.speed=Math.max(5,Math.min(80,speed));}
 start(element){if(!element||this.reduced()||element.scrollHeight<=element.clientHeight)return false;this.stop();this.element=element;this.running=true;this.previous=null;this.id=this.frame(this.tick);this.onState(true);return true;}
 tick(time){if(!this.running)return;if(this.reduced()){this.stop();return;}if(this.previous!==null){const seconds=Math.max(0,Math.min(.08,(time-this.previous)/1000));this.element.scrollTop+=this.speed*seconds;}this.previous=time;if(this.element.scrollTop>=this.element.scrollHeight-this.element.clientHeight-1){this.stop();return;}this.id=this.frame(this.tick);}
 stop(){if(this.id!==null)this.cancel(this.id);this.id=null;this.running=false;this.previous=null;this.onState(false);}
}

let readerMode='complete',readerAutoScroll=null,readerMotionMedia=null,readerFocus=false;
let readerWidth='standard',readerRepertoireContext=null;
const readerWidths={narrow:680,standard:960,wide:1200,full:null};
function readerDepartment(){if(typeof state==='undefined')return null;return state.departments.find(item=>item.id===readerRepertoireContext?.departmentId)||(typeof department==='function'?department():state.departments[0]);}
function readerRepertoireEntries(){const group=readerDepartment();if(!group||typeof state==='undefined')return [];const songs=new Map(state.songs.map(song=>[song.id,song]));return group.repertoire.map(entry=>({entry,song:songs.get(entry.songId)})).filter(item=>item.song);}
function readerToneFlats(song){const item=readerRepertoireContext&&readerRepertoireEntries().find(item=>item.song.id===song.id);return /b/.test(item?item.entry.key:song.key);}
function repertoireToneSteps(song,key){const original=song.key.match(/^([A-G][#b]?)(m?)$/),target=key?.match(/^([A-G][#b]?)(m?)$/);if(!original||!target||original[2]!==target[2])return null;for(let steps=0;steps<12;steps++)if(MusicTranspose.note(original[1],steps,false)===MusicTranspose.note(target[1],0,false))return steps;return null;}
function applyReaderRepertoireTone(song,force=false){if(!readerRepertoireContext)return;const item=readerRepertoireEntries().find(item=>item.song.id===song.id);if(!item)return;const saved=readerRepertoireContext.tones.get(song.id);let steps=!force&&saved?.key===item.entry.key?saved.steps:repertoireToneSteps(song,item.entry.key);if(steps===null){steps=0;toast('O tom do repertório muda entre maior e menor. A transposição preserva a qualidade dos acordes; confira o tom cadastrado.');}transposeSongId=song.id;transposeSteps=steps;readerRepertoireContext.tones.set(song.id,{key:item.entry.key,steps});}
function setReaderRepertoireContext(songId,enabled){if(enabled){const group=readerDepartment(),item=readerRepertoireEntries().find(item=>item.song.id===songId);if(!group||!item){readerRepertoireContext=null;return;}readerRepertoireContext={departmentId:group.id,tones:new Map()};stopCifraScroll();applyReaderRepertoireTone(item.song);}else if(readerRepertoireContext){stopCifraScroll();readerRepertoireContext=null;transposeSongId=null;}}
function readerRepertoireControls(){const entries=readerRepertoireEntries(),index=entries.findIndex(item=>item.song.id===currentSong.id);if(index<0)return '';if(!readerRepertoireContext)return button('Tocar repertório','cifra-repertoire-start','',true,'list');const previous=entries[index-1],next=entries[index+1];return button('← Anterior','cifra-repertoire','data-direction="-1" aria-label="Música anterior do repertório" '+(previous?'title="'+esc(previous.song.name)+'"':'disabled'),true)+'<span class="reader-song-position" role="status">Repertório · '+(index+1)+' / '+entries.length+'</span>'+button('Próxima →','cifra-repertoire','data-direction="1" aria-label="Próxima música do repertório" '+(next?'title="'+esc(next.song.name)+'"':'disabled'),true)+button('Tom do repertório','cifra-repertoire-tone','',true);}
function moveReaderRepertoire(direction){if(!readerRepertoireContext||![-1,1].includes(direction))return false;const entries=readerRepertoireEntries(),index=entries.findIndex(item=>item.song.id===currentSong.id),next=index>=0?entries[index+direction]:null;if(!next)return false;const current=entries[index];readerRepertoireContext.tones.set(currentSong.id,{key:current.entry.key,steps:transposeSteps});stopCifraScroll();currentSong=next.song;applyReaderRepertoireTone(currentSong);if(typeof rememberSong==='function')rememberSong(currentSong.id);updateCifraReader();const scroll=$('#cifra-reader')?.querySelector('.reader-scroll');if(scroll)scroll.scrollTop=0;const control=$('#cifra-reader')?.querySelector('[data-action="cifra-repertoire"][data-direction="'+direction+'"]');if(control&&!control.disabled)control.focus();else $('#cifra-reader')?.querySelector('#reader-title')?.focus();return true;}
function changeReaderWidth(value){if(!Object.hasOwn(readerWidths,value))return;readerWidth=value;updateCifraReader();}
function updateReaderWidth(dialog){const sheet=dialog.querySelector('.reader-sheet');sheet.style.maxWidth=readerWidths[readerWidth]===null?'none':readerWidths[readerWidth]+'px';const control=dialog.querySelector('#reader-width');if(control)control.value=readerWidth;}
try{const saved=localStorage.getItem('acervo-musical-reader-mode');if(['complete','map'].includes(saved))readerMode=saved;}catch{}
function reducedReaderMotion(){return window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches||false;}
function scrollState(running){const dialog=$('#cifra-reader');if(!dialog?.open)return;dialog.querySelectorAll('[data-action="cifra-scroll"]').forEach(control=>{control.textContent=running?'Pausar rolagem':'Iniciar rolagem';control.setAttribute('aria-pressed',String(running));});}
function autoScroller(){if(!readerAutoScroll){readerAutoScroll=new CifraAutoScroll({reduced:reducedReaderMotion,onState:scrollState});readerMotionMedia=window.matchMedia?.('(prefers-reduced-motion: reduce)');readerMotionMedia?.addEventListener?.('change',event=>{if(event.matches)readerAutoScroll.stop();});}return readerAutoScroll;}
function stopCifraScroll(){readerAutoScroll?.stop();}
function focusReaderForNavigation(){const sheet=$('#cifra-reader')?.querySelector('.reader-sheet');if(!sheet)return;sheet.setAttribute('tabindex','-1');sheet.setAttribute('aria-label','Leitura musical. Pressione Enter para a próxima música do repertório.');sheet.focus();}
function toggleReaderFocus(){readerFocus=!readerFocus;updateReaderFocus();if(readerFocus)focusReaderForNavigation();}
function updateReaderFocus(){const dialog=$('#cifra-reader');if(!dialog?.open)return;dialog.classList.toggle('musician-focus',readerFocus);const control=dialog.querySelector('[data-action="cifra-focus"]');if(control){control.textContent=readerFocus?'Mostrar controles':'Modo músico';control.setAttribute('aria-pressed',String(readerFocus));control.setAttribute('aria-expanded',String(!readerFocus));}const key=dialog.querySelector('.reader-current-key');if(key)key.textContent='Tom: '+MusicTranspose.chord(currentSong.key,transposeSteps,readerToneFlats(currentSong));}
function changeReaderMode(mode){if(!['complete','map'].includes(mode))return;readerMode=mode;try{localStorage.setItem('acervo-musical-reader-mode',mode);}catch{}updateCifraReader();}
function readerModel(song){return ChordSheet.parse(song.chords,song.lyrics||'');}
function renderReaderSheet(song){const model=readerModel(song),flats=readerToneFlats(song),shifted=ChordSheet.transposed(model,transposeSteps,flats);if(readerMode==='map'){const map=!model.hasLyrics&&!/[{}]/.test(song.chords)?MusicTranspose.text(song.chords,transposeSteps,flats):ChordSheet.map(shifted);return '<pre class="reader-map">'+esc(map)+'</pre>';}return ChordSheet.render(shifted,esc);}
document.addEventListener('keydown',event=>{
 const live=typeof LivePlaylist!=='undefined'&&LivePlaylist.active;
 if(event.key!=='Enter'||(!readerFocus&&!live)||!$('#cifra-reader')?.open||$('#pdf-reader')?.open||event.defaultPrevented||event.isComposing||event.ctrlKey||event.altKey||event.metaKey||event.shiftKey)return;
 if(event.target.matches('input,textarea,select,[contenteditable]')||event.target.closest?.('[contenteditable],button,a,summary,[role="button"]'))return;
 event.preventDefault();if(event.repeat)return;
 if(live)liveMove(1);
 else{
  if(!readerRepertoireContext)setReaderRepertoireContext(currentSong.id,true);
  if(!readerRepertoireContext){toast('Adicione esta música ao repertório para avançar com Enter.');return;}
  moveReaderRepertoire(1);
 }
 focusReaderForNavigation();
});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopCifraScroll();});
if(typeof window!=='undefined')window.addEventListener?.('beforeprint',stopCifraScroll);
document.addEventListener('change',event=>{if(event.target.id==='reader-width')changeReaderWidth(event.target.value);});
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target||!currentSong)return;const action=target.dataset.action;if(action==='cifra-repertoire')moveReaderRepertoire(Number(target.dataset.direction));if(action==='cifra-repertoire-start'){setReaderRepertoireContext(currentSong.id,true);updateCifraReader();}if(action==='cifra-repertoire-tone'){applyReaderRepertoireTone(currentSong,true);updateCifraReader();}if(action==='cifra-resources'){$('#cifra-reader').close();openSong(currentSong.id,true);}});
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target||!currentSong)return;const action=target.dataset.action;if(action==='cifra-focus')toggleReaderFocus();if(action==='cifra-mode'){changeReaderMode(target.dataset.mode);$('#cifra-reader').querySelector('[data-mode="'+target.dataset.mode+'"]')?.focus();}if(action==='cifra-scroll'){const scroller=autoScroller();if(scroller.running)scroller.stop();else if(!scroller.start($('#cifra-reader').querySelector('.reader-scroll')))toast(reducedReaderMotion()?'A preferência de movimento reduzido está ativa. Use a rolagem manual.':'Toda a cifra já está visível. Role manualmente ou aumente a fonte.');}});

const MusicTranspose=(()=>{
 const sharp=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'],flat=['C','Db','D','Eb','E','F','Gb','G','Ab','A','Bb','B'];
 const pitch={C:0,'C#':1,Db:1,D:2,'D#':3,Eb:3,E:4,Fb:4,'E#':5,F:5,'F#':6,Gb:6,G:7,'G#':8,Ab:8,A:9,'A#':10,Bb:10,B:11,Cb:11,'B#':0};
 function parseChord(value){if(typeof value!=='string'||value.length>128)return null;const normalized=value.replace(/♯/g,'#').replace(/♭/g,'b'),match=normalized.match(/^([A-G][#b]?)(.*?)(?:\/([A-G][#b]?))?$/);if(!match)return null;const suffix=match[2],token=/(?:maj|min|dim|aug|sus|add|omit|no|alt|dom|m|M|Δ|ø|°|º|\+|-|\d+|[#b]\d+|\/\d+|[(),]|\/(?=[#b\d]))/y;let index=0,depth=0;while(index<suffix.length){token.lastIndex=index;const part=token.exec(suffix);if(!part)return null;if(part[0]==='(')depth++;if(part[0]===')')depth--;if(depth<0||depth>8)return null;index=token.lastIndex;}if(depth)return null;return {root:match[1],bass:match[3]};}
 const pattern={test:value=>Boolean(parseChord(value))};
 function note(value,steps,flats){return (flats?flat:sharp)[((pitch[value]+steps)%12+12)%12];}
 function chord(value,steps,flats=false){const match=parseChord(value);if(!match||steps%12===0)return value;const {root,bass}=match;let result=note(root,steps,flats)+value.slice(root.length);if(bass)result=result.slice(0,-bass.length)+note(bass,steps,flats);return result;}
 function text(value,steps,flats=false){return value.split('\n').map(line=>{
  const label=line.match(/^(\s*(?:\[(?:Intro|Introdução|Estrofe|Pr[eé]-Refr[aã]o|Refrão|Verso|Ponte|Final|Primeira Parte|Segunda Parte)\]|(?:Intro|Introdução|Estrofe|Pr[eé]-Refr[aã]o|Refrão|Verso|Ponte|Final)\s*:)\s*)(.*)$/i);if(label)return label[1]+text(label[2],steps,flats);
  if(line.includes('['))return line.replace(/\[([^\]]+)\]/g,(all,item)=>pattern.test(item)?'['+chord(item,steps,flats)+']':all);
  return line.split('|').map(part=>{const tokens=part.trim().split(/\s+/).filter(Boolean);if(!tokens.length||!tokens.every(token=>pattern.test(token)||/^[():%–—-]+$/.test(token)))return part;return part.replace(/\S+/g,token=>chord(token,steps,flats));}).join('|');
 }).join('\n');}
 return {chord,text,note,isChord:value=>pattern.test(value)};
})();
let transposeSongId=null,transposeSteps=0,cifraFontSize=24;
function cifraToneControls(song){
 const key=MusicTranspose.chord(song.key,transposeSteps,readerToneFlats(song));
 const disabled=song.chords.trim()?'':'disabled';
 return button('− 1 tom','transpose','data-steps="-2" '+disabled,true)+button('− ½ tom','transpose','data-steps="-1" '+disabled,true)+'<strong role="status" aria-live="polite">Tom: '+esc(key)+'</strong>'+button('+ ½ tom','transpose','data-steps="1" '+disabled,true)+button('+ 1 tom','transpose','data-steps="2" '+disabled,true)+button('Tom original','transpose-reset',disabled,true);
}
function updateCifraReader(){
 const dialog=$('#cifra-reader');if(!dialog?.open)return;
 dialog.querySelector('#reader-title').textContent=currentSong.name;
 const repertoire=dialog.querySelector('.reader-repertoire');if(repertoire){repertoire.innerHTML=readerRepertoireControls();repertoire.hidden=!repertoire.innerHTML;}
 dialog.querySelector('.reader-tone').innerHTML=cifraToneControls(currentSong);
 const sheet=dialog.querySelector('.reader-sheet');sheet.innerHTML=currentSong.chords.trim()?renderReaderSheet(currentSong):'<div class="reader-missing">'+empty('Cifra em texto ainda não cadastrada')+button('Abrir materiais da música','cifra-resources','',true,'folder')+'</div>';sheet.style.fontSize=cifraFontSize+'px';dialog.querySelectorAll('[data-action="cifra-mode"]').forEach(control=>{control.setAttribute('aria-pressed',String(control.dataset.mode===readerMode));});
 dialog.querySelector('.reader-font-size').textContent=cifraFontSize+' px';
 updateReaderFocus();
 updateReaderWidth(dialog);
 const printMeta=dialog.querySelector('.reader-print-meta');if(printMeta)printMeta.textContent=(currentSong.artist?currentSong.artist+' · ':'')+'Tom: '+MusicTranspose.chord(currentSong.key,transposeSteps,readerToneFlats(currentSong));
}
function openCifraReader(){
 if(!currentSong||(!currentSong.chords.trim()&&!readerRepertoireContext)){toast('Cadastre a cifra em texto para acompanhar e alterar o tom.');return;}
 if(transposeSongId!==currentSong.id){stopCifraScroll();transposeSongId=currentSong.id;transposeSteps=0;}
 let dialog=$('#cifra-reader');
 if(!dialog){dialog=document.createElement('dialog');dialog.id='cifra-reader';dialog.className='cifra-reader';dialog.setAttribute('aria-labelledby','reader-title');document.body.append(dialog);
  dialog.addEventListener('close',()=>{stopCifraScroll();if(currentSong&&$('#detail').open){detail();$('#detail-content').querySelector('[data-action="cifra-reader"]')?.focus();}});
 }
 if(!dialog.open){dialog.innerHTML='<header class="reader-header"><div class="reader-title-row"><h2 id="reader-title" tabindex="-1" aria-live="polite">'+esc(currentSong.name)+'</h2><span class="reader-current-key key" role="status"></span><span class="reader-compact-scroll">'+button('Iniciar rolagem','cifra-scroll','aria-pressed="false"',true)+'</span>'+button('Modo músico','cifra-focus','aria-controls="reader-toolbar" aria-expanded="true" aria-pressed="false"',true)+button('Imprimir','cifra-print','',true,'file')+button('Voltar','cifra-reader-close','',true)+'</div><p class="reader-print-meta"></p><div class="reader-repertoire" role="group" aria-label="Navegação do repertório"></div><div class="reader-toolbar" id="reader-toolbar" role="group" aria-label="Ajustes da leitura"><div class="reader-tone transpose-toolbar" role="group" aria-label="Transposição"></div><div class="reader-font-controls" role="group" aria-label="Tamanho da letra">'+button('A−','cifra-font','data-size="-2" aria-label="Diminuir letra"',true)+'<span class="reader-font-size" role="status"></span>'+button('A+','cifra-font','data-size="2" aria-label="Aumentar letra"',true)+'</div><div class="reader-mode-controls" role="group" aria-label="Visualização da cifra">'+button('Cifra completa','cifra-mode','data-mode="complete" aria-pressed="true"',true)+button('Mapa de acordes','cifra-mode','data-mode="map" aria-pressed="false"',true)+'</div><label class="reader-width-control">Largura<select id="reader-width"><option value="narrow">Estreita</option><option value="standard">Padrão</option><option value="wide">Ampla</option><option value="full">Tela toda</option></select></label><div class="reader-scroll-controls">'+button('Iniciar rolagem','cifra-scroll','aria-pressed="false"',true,'play')+'<label class="scroll-speed">Velocidade<input id="reader-scroll-speed" type="range" min="5" max="80" value="24" step="1" aria-label="Velocidade de rolagem"><output id="reader-scroll-rate">24 px/s</output></label></div></div></header><div class="reader-scroll" tabindex="0" aria-label="Cifra para acompanhar"><div class="reader-sheet chord-sheet" aria-label="Conteúdo da cifra"></div></div>';dialog.showModal();}
 updateCifraReader();
 const speed=dialog.querySelector('#reader-scroll-speed');if(speed){speed.value=readerAutoScroll?.speed||24;dialog.querySelector('#reader-scroll-rate').textContent=speed.value+' px/s';speed.oninput=event=>{autoScroller().setSpeed(event.target.value);dialog.querySelector('#reader-scroll-rate').textContent=event.target.value+' px/s';};}scrollState(readerAutoScroll?.running||false);
}
function cifraContent(song){
 if(transposeSongId!==song.id){transposeSongId=song.id;transposeSteps=0;}
 const flats=/b/.test(song.key),key=MusicTranspose.chord(song.key,transposeSteps,flats);
 return pdfImportButton(song)+'<div class="transpose-toolbar" aria-label="Alterar tonalidade">'+cifraToneControls(song)+'</div>'+(song.chords.trim()?'<div class="asset-actions">'+button('Acompanhar em tela ampliada','cifra-reader','',false,'book')+'</div><p class="form-hint">Alterne entre cifra completa e mapa de acordes na tela ampliada. A consulta preserva o cadastro original.</p><div class="chord-sheet sheet-preview">'+(typeof renderFullSongSheet==='function'?renderFullSongSheet(song):renderReaderSheet(song))+'</div>':empty('Importe um PDF para extrair e conferir os acordes, ou cadastre sua cifra em texto.'))+(isAdmin()?button('Editor visual de acordes','song-chord-editor','data-id="'+esc(song.id)+'"',true,'edit'):'')+(isAdmin()?button('Cadastrar / editar cifra','edit','data-kind="songs" data-id="'+esc(song.id)+'"',true,'edit'):'');
}
document.addEventListener('click',event=>{
 const target=event.target.closest('[data-action]');if(!target||!currentSong)return;
 const action=target.dataset.action;
 if(action==='cifra-reader-close'){stopCifraScroll();$('#cifra-reader').close();return;}
 if(action==='cifra-reader'){openCifraReader();return;}
 if(action==='cifra-print'){stopCifraScroll();updateCifraReader();document.body.classList.add('printing-cifra');try{window.print();}finally{document.body.classList.remove('printing-cifra');}return;}
 if(action==='cifra-font'){cifraFontSize=Math.max(16,Math.min(48,cifraFontSize+Number(target.dataset.size)));updateCifraReader();return;}
 if(action==='transpose'||action==='transpose-reset'){
  if(!currentSong.chords.trim())return;
  if(transposeSongId!==currentSong.id){transposeSongId=currentSong.id;transposeSteps=0;}
  transposeSteps=action==='transpose-reset'?0:transposeSteps+Number(target.dataset.steps);
  openCifraReader();
  $('#cifra-reader').querySelector('[data-action="'+action+'"]'+(target.dataset.steps?'[data-steps="'+target.dataset.steps+'"]':''))?.focus();
 }
});

