const currentSection=()=>sections[page]||null;
const usesInstruments=()=>currentSection()?.type==='partitura';
function materialResources(song,type){
 const legacy={partitura:[['scoreLink','Partitura'],['pdfLink','Arquivo PDF']],cifra:[['gradeLink','Cifra / grade']],letra:[],projecao:[['projectionLink','Slides de projeção']],vozes:[['voicesLink','Kit de vozes']],videoaula:[['videoLink','Videoaula']]};
 return [...(legacy[type]||[]).filter(([field])=>song[field]&&(field!=='gradeLink'||!isGospelReference(song[field]))).map(([field,label])=>({id:field,type,instrument:'Geral',label,url:song[field]})),...(song.resources||[]).filter(resource=>resource.type===type)];
}
function departmentSearch(){return '<label class="department-search" for="global-search">Buscar no acervo<span class="global-search">'+icon('search')+'<input type="search" id="global-search" placeholder="Nome da música, artista ou gênero..." autocomplete="off"></span></label>';}
function genreFilter(){const genres=[...new Set(state.songs.map(song=>song.category.trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'));return '<label>Gênero (opcional)<select id="genre-filter"><option value="">Todos os gêneros</option>'+genres.map(name=>'<option value="'+esc(name)+'" '+(filters.category===name?'selected':'')+'>'+esc(name)+'</option>').join('')+'</select></label>';}
function selectPrompt(){return catalogueView();}
function catalogueSongs(){
 let songs=searchSongs(departmentSongs(),{query:filters.query,category:filters.category,favoritesOnly:page==='favoritos',favorites});
 const section=currentSection();
 if(section)songs=songs.filter(song=>materialResources(song,section.type).length>0||(section.type==='letra'&&(song.lyrics.trim()||(typeof songLyricText==='function'&&songLyricText(song).trim())))||(section.type==='cifra'&&(song.chords.trim()||song.category==='Gospel'||isGospelReference(song.gradeLink))));
 if(usesInstruments()&&filters.instrument)songs=songs.filter(song=>(filters.instrument==='Geral'&&section?.type==='letra'&&song.lyrics.trim())||(section?materialResources(song,section.type):Object.values(sections).flatMap(item=>materialResources(song,item.type))).some(resource=>resource.instrument===filters.instrument));
 return songs;
}
const CATALOGUE_PAGE_SIZE=48;
let catalogueMode=(typeof storage==='undefined'?'cards':storage.read('acervo-ui-catalogue-mode','cards'))==='list'?'list':'cards',cataloguePage=1,catalogueSignature='';
function catalogueViewControls(){return '<div class="view-switch" role="group" aria-label="Visualização das músicas">'+button('Cartões','catalogue-mode','data-mode="cards" aria-pressed="'+(catalogueMode==='cards')+'"',true,'folder')+button('Lista compacta','catalogue-mode','data-mode="list" aria-pressed="'+(catalogueMode==='list')+'"',true,'list')+'</div>';}
function updateCatalogue(){
 const grid=$('#song-grid');if(!grid)return;const list=catalogueSongs(),signature=JSON.stringify([page,filters.query,filters.category,filters.instrument,list.map(song=>song.id)]);
 if(signature!==catalogueSignature){cataloguePage=1;catalogueSignature=signature;}
 const pages=Math.max(1,Math.ceil(list.length/CATALOGUE_PAGE_SIZE));cataloguePage=Math.max(1,Math.min(cataloguePage,pages));
 grid.classList.toggle('catalogue-list',catalogueMode==='list');grid.innerHTML=catalogueCards(list.slice((cataloguePage-1)*CATALOGUE_PAGE_SIZE,cataloguePage*CATALOGUE_PAGE_SIZE))||empty(usesInstruments()&&filters.instrument?'Nenhum material cadastrado para '+filters.instrument+' nesta seção':page==='favoritos'?'Marque músicas com a estrela para encontrá-las aqui':'Nenhuma música encontrada');
 $('#result-count').textContent=list.length+' '+(list.length===1?'louvor encontrado':'louvores encontrados');
 const pager=$('#catalogue-pagination');if(pager){pager.hidden=pages===1;pager.innerHTML=pages>1?button('← Anterior','catalogue-page','data-page="'+(cataloguePage-1)+'" '+(cataloguePage===1?'disabled':''),true)+'<span role="status">'+((cataloguePage-1)*CATALOGUE_PAGE_SIZE+1)+'–'+Math.min(list.length,cataloguePage*CATALOGUE_PAGE_SIZE)+' de '+list.length+' · Página '+cataloguePage+' de '+pages+'</span>'+button('Próxima →','catalogue-page','data-page="'+(cataloguePage+1)+'" '+(cataloguePage===pages?'disabled':''),true):'';}
 $$('[data-action="catalogue-mode"]').forEach(control=>control.setAttribute('aria-pressed',String(control.dataset.mode===catalogueMode)));
}
function sectionMaterialContent(song,section=currentSection()){if(!section)return null;const resources=materialResources(song,section.type).filter(resource=>section.type!=='partitura'||!usesInstruments()||!filters.instrument||resource.instrument===filters.instrument);const links='<div class="asset-actions file-grid">'+resources.map(resource=>resourceButton(resource,section.icon,song.id)).join('')+'</div>';if(section.type==='letra')return (song.lyrics?'<div class="lyrics">'+esc(song.lyrics)+'</div>':empty('Letra ainda não cadastrada'))+links+(isAdmin()&&song.lyrics.trim()?button('Criar cifra a partir desta letra','lyrics-chord-editor','data-id="'+esc(song.id)+'"',true,'edit'):'');
 if(section.type==='cifra')return cifraContent(song)+links;
 if(section.type==='projecao')return (song.lyrics?button('Apresentar letra','project','',false,'play'):empty('Letra ainda não cadastrada'))+links;
 return '<h3>'+esc(section.title)+'</h3>'+links+(!resources.length?empty('Material ainda não cadastrado'):'')+'<div class="drive-note"><strong>Observações para ensaio</strong><p>'+esc(song.notes||'Sem observações cadastradas.')+'</p></div>';
}
function editResources(id){if(!isAdmin())return;const song=state.songs.find(item=>item.id===id);if(!song)return;let dialog=$('#resource-editor');if(!dialog){dialog=document.createElement('dialog');dialog.id='resource-editor';document.body.append(dialog);}dialog.innerHTML='<div class="dialog-head"><div><h2>Materiais por instrumento</h2><p>'+esc(song.name)+'</p></div><button class="button secondary" data-close="resource-editor" aria-label="Voltar">← Voltar</button></div><div class="tab-content"><div class="resource-list">'+(song.resources||[]).map(resource=>'<div class="user-row"><div><strong>'+esc(resource.label)+'</strong><p>'+esc(resource.instrument)+' · '+esc(Object.values(sections).find(section=>section.type===resource.type)?.title)+'</p></div>'+button('Remover','remove-resource','data-song="'+esc(id)+'" data-id="'+esc(resource.id)+'"',true)+'</div>').join('')+'</div><form id="resource-form" class="account-form"><label>Seção<select name="type">'+Object.values(sections).map(section=>'<option value="'+section.type+'" '+(section.type===currentSection()?.type?'selected':'')+'>'+esc(section.title)+'</option>').join('')+'</select></label><label id="resource-instrument-field" '+(!usesInstruments()?'hidden':'')+'>Instrumento ou voz<input name="instrument" list="instrument-options" value="Geral" required maxlength="100"><datalist id="instrument-options">'+instrumentOptions().map(name=>'<option value="'+esc(name)+'"></option>').join('')+'</datalist></label><label>Nome do material<input name="label" required maxlength="200"></label><label>Endereço do arquivo<input type="url" name="url" required placeholder="https://…"></label><button class="button" type="submit">Salvar material</button></form></div>';dialog.showModal();const typeSelect=$('#resource-form').querySelector('[name=type]');typeSelect.onchange=()=>{$('#resource-instrument-field').hidden=typeSelect.value!=='partitura';};$('#resource-form').onsubmit=async event=>{event.preventDefault();const submit=event.target.querySelector('[type="submit"]');submit.disabled=true;try{const values=Object.fromEntries(new FormData(event.target));values.url=validURL(values.url);if(values.type!=='partitura')values.instrument='Geral';const next=structuredClone(state);next.songs.find(item=>item.id===id).resources.push({id:uid(),...values});if(await persist(next)){dialog.close();render();if($('#detail').open){currentSong=state.songs.find(item=>item.id===id);detail();}toast('Material cadastrado.');}}catch(error){toast(error.message);}finally{submit.disabled=false;}};}
async function removeResource(songId,id){if(!isAdmin())return;const next=structuredClone(state),song=next.songs.find(item=>item.id===songId);if(!song)return;song.resources=song.resources.filter(resource=>resource.id!==id);if(await persist(next)){$('#resource-editor').close();editResources(songId);render();if($('#detail').open){currentSong=state.songs.find(item=>item.id===songId);detail();}}}

