 const songs=departmentSongs(),availableInstruments=[...new Set([...instrumentOptions(),...songs.flatMap(song=>(song.resources||[]).filter(resource=>!section||resource.type===section.type).map(resource=>resource.instrument))])];
 return heading('BIBLIOTECA',title,liked?'Suas músicas preferidas, sempre à mão.':'Todas as músicas em um só lugar. Filtre e encontre o que precisa.',isAdmin()?button('Adicionar música',!section||section.type==='cifra'?'add-cifra':'upload-song','',false,'plus'):'')+'<section class="library-tools" aria-label="Filtros do acervo"><div class="module-toolbar">'+genreFilter()+(usesInstruments()?'<label>Instrumento / voz<select id="instrument-filter"><option value="">Todos os instrumentos</option>'+availableInstruments.map(name=>'<option '+(filters.instrument===name?'selected':'')+'>'+esc(name)+'</option>').join('')+'</select></label>':'')+'<div class="library-actions">'+(!section||section.type==='cifra'?pdfImportButton():'')+(isAdmin()&&(!section||section.type==='cifra')?button('Catálogo gospel','gospel-catalogue','',true,'book'):'')+'</div></div><div class="result-line"><span id="result-count" role="status"></span>'+catalogueViewControls()+'<span class="library-context">'+esc(liked?'Favoritos deste dispositivo':section?.title||'Acervo único')+'</span></div></section><div class="song-grid" id="song-grid"></div><nav class="catalogue-pagination" id="catalogue-pagination" aria-label="Páginas de músicas" hidden></nav>';
