function catalogueCards(list){
 const section=currentSection();return list.map(song=>{const materials=songMaterials(song),resources=section?materialResources(song,section.type).filter(resource=>!usesInstruments()||!filters.instrument||resource.instrument===filters.instrument):[];
 return '<article class="song-card"><div class="song-card-body"><div class="song-card-heading"><span class="music-mark">'+icon(section?.icon||'music')+'</span><div class="song-title"><h2>'+esc(song.name)+'</h2><p class="artist">'+esc(song.artist||'Artista não informado')+'</p></div>'+favoriteButton(song)+'</div><div class="song-metadata"><span class="key">Tom '+esc(song.key)+'</span><span class="bpm">'+esc(song.bpm)+' BPM</span>'+(song.category?'<span class="genre-tag">'+esc(song.category)+'</span>':'')+'</div><div class="materials">'+materials.map(item=>'<span>'+icon(item.icon)+esc(item.title)+'</span>').join('')+'</div>'+(section&&resources.length&&usesInstruments()?'<p class="resource-summary">'+esc([...new Set(resources.map(resource=>resource.instrument))].join(' · '))+'</p>':'')+(section?.type==='cifra'&&!song.chords.trim()?'<p class="material-pending">'+(resources.length?'PDF / arquivo disponível. Prepare a cifra para transpor.':'Cadastre ou importe a cifra para acompanhar.')+'</p>':'')+button(section?'Abrir '+section.title.toLocaleLowerCase('pt-BR'):'Abrir música','song','data-id="'+esc(song.id)+'" aria-label="Abrir '+esc(song.name)+'"',false,'arrow')+'</div></article>';}).join('');
}

