 const form=$('#member-registration');if(form)form.onsubmit=async event=>{event.preventDefault();if(!isAdmin())return;const submit=event.target.querySelector('button');submit.disabled=true;try{await api('/api/members',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});event.target.reset();$('#registration-result').textContent='E-mail cadastrado. Acesso de consulta liberado.';}catch(error){toast(error.message);}finally{submit.disabled=false;}};
