async function deleteInstrument(id){if(!isAdmin())return;const item=state.instruments.find(value=>value.id===id);if(!item||id==='geral')return;const used=state.songs.some(song=>(song.resources||[]).some(resource=>resource.instrument===item.name));if(!confirm('Excluir '+item.name+' do cadastro?'+(used?' Os materiais existentes serão preservados e classificados como Geral.':'')))return;const next=structuredClone(state);next.instruments=next.instruments.filter(value=>value.id!==id);next.songs.forEach(song=>(song.resources||[]).forEach(resource=>{if(resource.instrument===item.name)resource.instrument='Geral';}));if(await persist(next)){if(filters.instrument===item.name)filters.instrument='';render();toast('Cadastro excluído. Os arquivos foram preservados.');}}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action="delete-instrument"]');if(target)deleteInstrument(target.dataset.id);});

const navigationTrail=[];
let navigationPosition=null;
function rememberNavigation(){const current={page,query:filters.query,instrument:filters.instrument,category:filters.category};if(navigationPosition&&navigationPosition.page!==page)navigationTrail.push(navigationPosition);navigationPosition=current;}
