async function bootCatalogue(){
 const cover=document.createElement('div');cover.className='loading-cover';cover.textContent='Abrindo seu acervo…';document.body.append(cover);
 try{const me=await api('/api/me');authenticatedUser=me.user;const response=await api('/api/data');state=validate(response.data);revision=response.revision;departmentId=state.departments[0].id;
 const user=me.user?.username||'Usuário',role=isAdmin()?'Administrador':'Consulta',initial=user.trim().slice(0,1).toUpperCase();
 $('.topbar').innerHTML='<button class="icon-button menu-toggle" id="menu-toggle" aria-label="Abrir menu" aria-controls="sidebar" aria-expanded="false">'+icon('menu')+'</button><div class="page-context" id="current-page-label">Início</div><label class="header-search" for="global-search"><span class="sr-only">Pesquisar em todo o acervo</span>'+icon('search')+'<input type="search" id="global-search" placeholder="Buscar músicas, artistas ou gêneros…" autocomplete="off"><kbd aria-hidden="true">/</kbd></label><div class="account-bar"><span class="avatar" aria-hidden="true">'+esc(initial)+'</span><span class="user-identity"><strong>'+esc(user)+'</strong><small>'+role+'</small></span><a class="icon-button" href="#configuracoes" aria-label="Configurações">'+icon('settings')+'</a>'+(me.user?.id?button('Sair','logout','',true):'')+'</div>';
 $('#menu-toggle').onclick=()=>toggleMenu(!document.body.classList.contains('menu-open'));$('#menu-backdrop').onclick=()=>toggleMenu(false);render();bindResponsiveMenu();cover.remove();
 }catch(error){cover.innerHTML='<div><h2>Não foi possível abrir o acervo</h2><p>'+esc(error.message)+'</p><button class="button" onclick="location.reload()">Tentar novamente</button></div>';}
}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(target){if(target.dataset.action==='go-home'){event.preventDefault();goHome();}if(target.dataset.action==='go-back')goBack();if(target.dataset.action==='resources')editResources(target.dataset.id);if(target.dataset.action==='remove-resource')removeResource(target.dataset.song,target.dataset.id);}if(event.target.closest('a[href^="#"]')&&document.body.classList.contains('menu-open'))toggleMenu(false);});
document.addEventListener('keydown',event=>{if(event.key==='/'&&!event.ctrlKey&&!event.metaKey&&!event.altKey&&!event.target.matches('input,textarea,select,[contenteditable]')&&!document.querySelector('dialog[open]')){event.preventDefault();$('#global-search')?.focus();}});

document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target)return;if(target.dataset.action==='catalogue-mode'&&['cards','list'].includes(target.dataset.mode)){catalogueMode=target.dataset.mode;try{storage.write('acervo-ui-catalogue-mode',catalogueMode);}catch{}updateCatalogue();}if(target.dataset.action==='catalogue-page'){const requested=Number(target.dataset.page);if(!Number.isInteger(requested))return;cataloguePage=requested;updateCatalogue();$('#main').focus();$('#main').scrollIntoView?.({block:'start'});}});

const localFileURLs=new Map();
function fileDatabase(){return new Promise((resolve,reject)=>{const request=indexedDB.open('acervo-musical-files',1);request.onupgradeneeded=()=>request.result.createObjectStore('files');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(Error('Não foi possível acessar os arquivos deste navegador.'));});}
async function localFileStore(id,file){const database=await fileDatabase();try{await new Promise((resolve,reject)=>{const transaction=database.transaction('files','readwrite');transaction.objectStore('files').put(file,id);transaction.oncomplete=resolve;transaction.onerror=()=>reject(Error('Não foi possível salvar o arquivo neste navegador.'));transaction.onabort=()=>reject(Error('Não há espaço suficiente para salvar o arquivo.'));});}finally{database.close();}}
async function localFileRead(id){const database=await fileDatabase();try{return await new Promise((resolve,reject)=>{const request=database.transaction('files').objectStore('files').get(id);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(Error('Não foi possível abrir o arquivo.'));});}finally{database.close();}}
function resourceButton(resource,ico='file',songId=''){if(/\.pdf(?:$|[?#])/i.test(resource.label+' '+resource.url)||/\.pdf$/i.test(resource.label))return button(resource.label,'pdf-open','data-song="'+esc(songId)+'" data-resource="'+esc(resource.id)+'"',true,ico);if(resource.storage==='local'&&resource.fileId)return button(resource.label+(resource.type==='partitura'?' · '+resource.instrument:''),'open-upload','data-id="'+esc(resource.fileId)+'"',true,ico);return external(resource.url,resource.label+' · '+resource.instrument,ico);}
async function openLocalUpload(id){try{let url=localFileURLs.get(id);if(!url){const file=await localFileRead(id);if(!file)throw Error('Arquivo não encontrado neste navegador.');url=URL.createObjectURL(file);localFileURLs.set(id,url);}const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener';link.click();}catch(error){toast(error.message);}}
async function saveUploadedFile(file,onProgress,metadata={}){
 if(location.protocol==='file:'){const id=uid();await localFileStore(id,file);onProgress(100);return {storage:'local',fileId:id,url:''};}
 const started=await api('/api/uploads',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:file.name,size:file.size,...metadata})});
 try{const count=Math.ceil(file.size/started.partSize);for(let index=0;index<count;index++){await api('/api/uploads/'+started.id+'/'+index,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file.slice(index*started.partSize,(index+1)*started.partSize)});onProgress(Math.round((index+1)*100/count));}const done=await api('/api/uploads/'+started.id+'/complete',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});return {storage:'server',fileId:done.id,url:new URL(done.url,location.origin).href};}catch(error){try{await api('/api/uploads/'+started.id+'/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});}catch{}throw error;}
}
