const liveBaseOpenPdfFile=openPdfFile;
openPdfFile=async function(file,songId='',resource=null,options={}){await liveBaseOpenPdfFile(file,songId,resource,options);if(!LivePlaylist.active||!pdfSession||pdfSession.songId!==currentSong?.id||pdfSession.liveNavigation)return;pdfSession.liveNavigation=true;const entries=liveEntries(),index=liveCurrentIndex(),next=entries[index+1];$('#pdf-reader').querySelector('.pdf-page-tools').insertAdjacentHTML('beforeend','<div class="live-pdf-navigation" role="group" aria-label="Trocar música da playlist">'+button('← Música anterior','live-pdf-move','data-direction="-1" '+(index<=0?'disabled':''),true)+button(next?'Próxima música: '+next.song.name+' →':'Fim da playlist','live-pdf-move','data-direction="1" '+(!next?'disabled':''),true)+'</div>');};
