 const links='<a href="#inicio" data-page="inicio">'+icon('home')+'<span>Início</span></a>'+(isAdmin()?'<a href="#gerenciar" data-page="gerenciar">'+icon('settings')+'<span>Gerenciar</span></a>':'');
 $('#sidebar nav').innerHTML=links;
