 $$('[data-page]').forEach(link=>{const active=link.dataset.page===SimpleUI.screen;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});
 $$('[data-admin-only]').forEach(el=>{el.hidden=!isAdmin();});
