function simpleFilters(){return '<section class="simple-filters" aria-label="Filtros da biblioteca"><div class="scope-tabs" role="group" aria-label="Selecionar músicas">'+[['all','Todas'],['favorites','Favoritos'],['recent','Recentes']].map(([value,label])=>button(label,'simple-scope','data-scope="'+value+'" aria-pressed="'+(SimpleUI.scope===value)+'"',true)).join('')+'</div><div class="simple-selects">'+librarySelect('material-filter','Material',[['','Todos os materiais'],...Object.values(sections).map(s=>[s.type,s.title]),['pdf','PDF']],filters.material)+genreFilter()+'<details class="more-filters"><summary>Mais filtros</summary><div>'+librarySelect('key-filter','Tom',[['','Todos os tons'],...keys.map(key=>[key,key])],filters.key)+librarySelect('instrument-filter','Instrumento',[['','Todos'],...[...new Set([...instrumentOptions(),...state.songs.flatMap(s=>(s.resources||[]).map(r=>r.instrument))])].map(name=>[name,name])],filters.instrument)+librarySelect('content-filter','Conteúdo',[['','Qualquer conteúdo'],['complete','Cifra e letra'],['partial','Texto parcial'],['reference','Referências / arquivos']],filters.content)+'</div></details>'+button('Limpar','simple-clear','',true)+'</div></section>';}
function simpleLibrary(managing=false){return '<div class="simple-heading"><div><p class="eyebrow">'+(managing?'ADMINISTRAÇÃO':'SUA BIBLIOTECA')+'</p><h1>'+(managing?'Gerenciar':'Sua música, à mão.')+'</h1><p class="subtitle">'+(managing?'Músicas, arquivos e organização em um só lugar.':'Encontre, abra e toque.')+'</p></div>'+(managing?button('Adicionar música','add-cifra','',false,'plus'):simpleTools())+'</div>'+(managing?'<div class="manage-tools">'+button('Importar PDF','pdf-import','',true)+button('Importar texto','library-import','',true)+button('Associar partitura','score-attach','',true)+'<details class="simple-tools"><summary>Mais opções</summary><div>'+button('Enviar arquivo','simple-upload','',true)+button('Catálogo gospel','gospel-catalogue','',true)+'<a href="#gerenciar/instrumentos">Instrumentos e vozes</a><a href="#gerenciar/cadastroemail">Cadastrar acesso</a><a href="#gerenciar/acessos">Gerenciar acessos</a>'+button('Usuários','users','',true)+button('Exportar acervo','export','',true)+button('Importar acervo','import','',true)+'</div></details></div>':'')+simpleFilters()+'<div class="result-line"><span id="result-count" role="status" aria-live="polite"></span></div><div class="song-grid simple-song-list" id="song-grid"></div><nav id="catalogue-pagination" class="catalogue-pagination" aria-label="Páginas de músicas" hidden></nav>';}
const simpleBaseSongs=catalogueSongs;
catalogueSongs=function(){let list=simpleBaseSongs();if(SimpleUI.scope==='favorites')list=list.filter(s=>favorites.includes(s.id));if(SimpleUI.scope==='recent')list=recentSongs.map(id=>list.find(s=>s.id===id)).filter(Boolean);if(filters.material==='audio')list=list.filter(song=>audioForSong(song));else if(filters.material==='pdf')list=list.filter(song=>Boolean(song.pdfLink||song.scoreLink?.toLowerCase().includes('.pdf')||song.gradeLink?.toLowerCase().includes('.pdf')||(song.resources||[]).some(resource=>/\.pdf(?:$|[?#])/i.test(resource.label+' '+resource.url))));else if(filters.material)list=list.filter(song=>songMaterials(song).some(material=>material.type===filters.material));if(filters.instrument&&!usesInstruments())list=list.filter(s=>(s.resources||[]).some(r=>r.instrument===filters.instrument));return list;};
catalogueCards=function(list){return list.map(song=>'<article class="simple-song-row"><button class="simple-song-open" data-action="song" data-id="'+esc(song.id)+'"><span class="simple-song-icon">'+icon('music')+'</span><span class="simple-song-title"><strong>'+esc(song.name)+'</strong><small>'+esc(song.artist||'Artista não informado')+'</small></span><span class="simple-song-materials">'+songMaterials(song).map(s=>esc(s.title)).join(' · ')+'</span>'+(audioForSong(song)?'<span class="audio-available" aria-label="Tem áudio disponível">'+icon('play')+'</span>':'')+'<span class="simple-song-key">Tom '+esc(song.key)+'<small>'+esc(song.bpm)+' BPM</small></span></button>'+favoriteButton(song)+(SimpleUI.screen==='gerenciar'?'<div class="simple-row-actions">'+button('Editar','edit','data-kind="songs" data-id="'+esc(song.id)+'" aria-label="Editar '+esc(song.name)+'"',true,'edit')+button('Áudio','resources','data-id="'+esc(song.id)+'" aria-label="Gerenciar áudio de '+esc(song.name)+'"',true,'play')+button('Excluir','delete-song','data-id="'+esc(song.id)+'" aria-label="Excluir '+esc(song.name)+'"',true)+'</div>':'')+'</article>').join('');};
const simpleBaseUpdate=updateCatalogue;
updateCatalogue=function(){simpleBaseUpdate();const count=$('#result-count');if(count)count.textContent=count.textContent.replace(/louvor encontrado/,'música encontrada').replace(/louvores encontrados/,'músicas encontradas');const grid=$('#song-grid');if(grid&&!catalogueSongs().length)grid.innerHTML='<div class="simple-empty">'+icon('music')+'<h2>'+(state.songs.length?'Nenhuma música por aqui':'Sua biblioteca está pronta para começar')+'</h2><p>'+(SimpleUI.scope==='favorites'?'Toque na estrela de uma música para guardá-la aqui.':SimpleUI.scope==='recent'?'As músicas que você abrir aparecerão aqui.':state.songs.length?'Tente outro termo ou limpe os filtros.':'As músicas adicionadas ao acervo aparecerão aqui.')+'</p>'+(state.songs.length?button('Limpar busca e filtros','simple-clear','',true):isAdmin()?'<a class="button" href="#gerenciar">Adicionar ao acervo</a>':'')+'</div>';};
function updateHomeSearch(){const host=$('#home-results'),clear=$('[data-action="simple-clear-home"]');if(!host)return;if(clear)clear.hidden=!filters.query;const list=filters.query?searchSongs(state.songs,{query:filters.query}).slice(0,12):[];host.innerHTML=!filters.query?'':list.length?'<div class="home-result-list">'+catalogueCards(list)+'</div>':'<p class="home-search-empty" role="status">Nenhuma m&#250;sica encontrada. Confira o nome ou artista.</p>';}
function bindSimpleSearch(){const home=$('#home-search'),library=$('#global-search');if(home){home.value=filters.query;home.oninput=event=>{filters.query=event.target.value;updateHomeSearch();};}if(library){library.value=filters.query;library.oninput=event=>{filters.query=event.target.value;cataloguePage=1;const clear=$('[data-action="simple-clear-library"]');if(clear)clear.hidden=!filters.query;updateCatalogue();};}}
function openMemberSongForm(){
 if(authenticatedUser?.role!=='member')return;
 let dialog=$('#member-song-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='member-song-dialog';document.body.append(dialog);}
 dialog.innerHTML='<div class="dialog-head"><div><h2>Adicionar música</h2><p>Compartilhe a cifra e as referências com o repertório.</p></div><button class="button secondary" type="button" data-close="member-song-dialog">Cancelar</button></div><form id="member-song-form" class="account-form member-song-form"><label>Título<input name="name" required maxlength="200"></label><label>Artista / intérprete<input name="artist" maxlength="200"></label><div class="member-song-grid"><label>Tom original<select name="originalKey">'+keys.map(key=>'<option>'+esc(key)+'</option>').join('')+'</select></label><label>Tom da cifra<select name="key">'+keys.map(key=>'<option>'+esc(key)+'</option>').join('')+'</select></label><label>Andamento (BPM)<input name="bpm" type="number" min="30" max="250" value="80"></label><label>Gênero<input name="category" maxlength="100"></label></div><label>Cifra completa — acordes e letra juntos<textarea name="chords" maxlength="20000" rows="8" placeholder="[Estrofe]\n[C]Letra com [G]acordes"></textarea></label><label>Letra independente (opcional)<textarea name="lyrics" maxlength="20000" rows="5"></textarea></label><label>Observações para ensaio<textarea name="notes" maxlength="20000" rows="3"></textarea></label><details class="member-links"><summary>Materiais e links</summary><label>Partitura (link)<input name="scoreLink" type="url" maxlength="2000" placeholder="https://…"></label><label>Cifra / grade (link)<input name="gradeLink" type="url" maxlength="2000" placeholder="https://…"></label><label>PDF (link)<input name="pdfLink" type="url" maxlength="2000" placeholder="https://…"></label><label>Vídeo de referência (link)<input name="videoLink" type="url" maxlength="2000" placeholder="https://…"></label><label>Kit de vozes (link)<input name="voicesLink" type="url" maxlength="2000" placeholder="https://…"></label><label>Slides de apresentação (link)<input name="projectionLink" type="url" maxlength="2000" placeholder="https://…"></label></details><label>Áudio de referência (MP3, WAV, M4A, OGG, AAC ou FLAC)<input name="audio" type="file" accept=".mp3,.wav,.m4a,.ogg,.aac,.flac,audio/mpeg,audio/wav,audio/mp4,audio/ogg,audio/aac,audio/flac"></label><p class="form-hint">Áudio opcional · até 200 MB. O envio é privado e fica associado a esta música.</p><p id="member-song-status" role="status" aria-live="polite"></p><button class="button" type="submit">Salvar música</button></form>';
 dialog.showModal();const form=$('#member-song-form');form.onsubmit=async event=>{event.preventDefault();if(authenticatedUser?.role!=='member')return;const data=new FormData(form),submit=form.querySelector('[type="submit"]'),status=$('#member-song-status'),file=data.get('audio');const song=Object.fromEntries(['name','artist','key','originalKey','category','chords','lyrics','notes','scoreLink','gradeLink','pdfLink','videoLink','voicesLink','projectionLink'].map(name=>[name,String(data.get(name)||'').trim()]));song.bpm=Number(data.get('bpm')||80);if(!song.name){status.textContent='Informe o título da música.';return;}if(file?.size&&(!/\.(mp3|wav|m4a|ogg|aac|flac)$/i.test(file.name)||file.size>200*1024*1024)){status.textContent='Escolha um áudio compatível de até 200 MB.';return;}submit.disabled=true;form.querySelectorAll('input,textarea,select,button').forEach(control=>{control.disabled=true;});let uploaded=null,created=false;try{if(file?.size){status.textContent='Enviando áudio… 0%';uploaded=await saveUploadedFile(file,value=>status.textContent='Enviando áudio… '+value+'%',{purpose:'song-audio'});song.audioFileId=uploaded.fileId;}status.textContent='Salvando música…';await api('/api/songs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({song})});created=true;const response=await api('/api/data');state=validate(response.data);revision=response.revision;dialog.close();render();toast('Música adicionada ao repertório.');}catch(error){if(!created&&uploaded?.storage==='server'&&uploaded.fileId)try{await api('/api/uploads/'+uploaded.fileId,{method:'DELETE'});}catch{}status.textContent=error.message;toast(error.message);}finally{if(dialog.open){form.querySelectorAll('input,textarea,select,button').forEach(control=>{control.disabled=false;});submit.disabled=false;}}};
}
renderCatalogue=function(){
 if(AppRuntime.expired){$('#main').innerHTML='<h1>Cópia offline expirada</h1><p>Conecte-se e reabra o aplicativo para validar sua conta.</p>';return;}
 const route=simpleRoute();
 if(route.screen==='gerenciar'&&!isAdmin()){replaceSimpleHash('#inicio');toast('Gerenciar está disponível somente para administradores.');return renderCatalogue();}
 if(route.screen==='musica'){
  if(!state.songs.some(song=>song.id===route.id)){$('#detail').close();$('#main').innerHTML='<div class="simple-empty"><h1>Música não encontrada</h1><p>Ela pode ter sido removida do acervo.</p><a class="button" href="#inicio">Voltar ao início</a></div>';return;}
  if(!$('#detail').open||currentSong?.id!==route.id)openSong(route.id,false);
  return;
 }
 if($('#detail').open)$('#detail').close();
 page=route.page;SimpleUI.screen=route.screen;
 if(route.scope)SimpleUI.scope=route.scope;
 if(route.material)filters.material=route.material;
 if(route.screen==='gerenciar')SimpleUI.scope='all';
 replaceSimpleHash(simpleHash(route));departmentId=state.departments[0].id;
 document.body.classList.toggle('home-screen',page==='inicio'&&!AppRuntime.expired);
 document.body.classList.toggle('admin-screen',route.screen==='gerenciar');
 simpleNavigation();$('#main').classList.add('simple-main');
 const views={inicio:homeView,ensaio:repertoireView,playlist:playlistView,configuracoes:settingsView,cadastroemail:registrationView,acessos:accessView,instrumentos:instrumentRegistryView};
 $('#main').innerHTML=(AppRuntime.offline||globalThis.navigator?.onLine===false?runtimeStatus():'')+(views[page]?'<div class="simple-subview"><a class="text-button" href="'+(route.screen==='gerenciar'?'#gerenciar':'#inicio')+'">← '+(route.screen==='gerenciar'?'Gerenciar':'Biblioteca')+'</a>'+views[page]()+'</div>':simpleLibrary(route.screen==='gerenciar'));
 if(page==='inicio'){const recent=new Map(state.songs.map(song=>[song.id,song]));const grid=$('#song-grid');if(grid)grid.innerHTML=catalogueCards(recentSongs.map(id=>recent.get(id)).filter(Boolean).slice(0,3));}
 if(page==='configuracoes')$('#main').insertAdjacentHTML?.('beforeend','<div class="asset-actions">'+button('Consultar cópia baixada','app-offline-open','',true)+button('Exportar diagnóstico','app-diagnostics','',true)+'</div>');
 $('#main').classList.toggle('live-hub-page',page==='playlist'&&!AppRuntime.expired);
 const primaryPage=['inicio','playlist','ensaio'].includes(page);if(primaryPage){const subview=$('#main .simple-subview');subview?.querySelector('.text-button')?.remove();subview?.classList.remove('simple-subview');}
 bindPilotForms();bindInstrumentForm();bindExperience();bindSimpleSearch();
 if(page==='inicio')$('#song-grid');
 if(page==='playlist'){const search=$('#live-library-search');if(search)search.oninput=event=>{$('#live-library-results').innerHTML=liveHubRows(liveEntries(),event.target.value);};}
 if(page==='inicio')updateHomeSearch();
 if(!views[page]){updateCatalogue();for(const [id,key]of [['genre-filter','category'],['material-filter','material']]){const control=$('#'+id);if(control){control.value=filters[key]||'';control.onchange=event=>{filters[key]=event.target.value;cataloguePage=1;updateCatalogue();};}}}
 if(route.adminAction&&route.screen==='gerenciar'){if(route.adminAction==='new')edit('songs',null);else if(route.adminAction==='edit'&&state.songs.some(song=>song.id===route.id)){edit('songs',route.id);const fields=$('#fields');if(fields)fields.innerHTML+='<div class="audio-admin-shortcut">'+button('Gerenciar áudio','resources','data-id="'+esc(route.id)+'"',true,'play')+'</div>';}}
};
const simpleOpenSong=openSong;
goHome=function(){SimpleUI.scope='all';Object.assign(filters,{query:'',category:'',material:'',key:'',instrument:'',content:''});location.hash='#inicio';render();};
openSong=function(id,fromRepertoire=page==='ensaio'){
 if(SimpleUI.screen==='ensaio')fromRepertoire=true;
 if(recording||!state.songs.some(s=>s.id===id))return simpleOpenSong(id,fromRepertoire);
 if(!location.hash.startsWith('#musica/')){SimpleUI.returnHash=location.hash||'#inicio';SimpleUI.returnFocus=id;}
 simpleOpenSong(id,fromRepertoire);
 const song=currentSong,selected=Object.values(sections).find(section=>section.type===filters.material);
 if(selected){currentTab=selected.tab;detail();}
 else if(!song.chords.trim()&&!song.lyrics.trim()&&(song.pdfLink||song.scoreLink||scoreResources(song).length)){currentTab='arquivos';detail();}
 const hash='#musica/'+encodeURIComponent(id);if(location.hash!==hash){if(globalThis.history?.pushState)history.pushState(null,'',hash);else location.hash=hash;}
};
const simpleBaseDetail=detail;
detail=function(){pauseSongAudio();simpleBaseDetail();const content=$('#detail-content');const actions=content.querySelector('.dialog-head .actions');if(actions)actions.innerHTML=favoriteButton(currentSong)+(isAdmin()?button('Gerenciar música','simple-manage-song','data-id="'+esc(currentSong.id)+'"',true,'edit'):'')+'<button class="button secondary" data-close="detail">← Biblioteca</button>';const resource=audioForSong(currentSong);if(resource){content.innerHTML+=audioPlayerMarkup(resource);bindSongAudio(resource);}};
function pauseSongAudio(){const audio=$('#song-audio');if(audio){audio.pause?.();audio.removeAttribute?.('src');audio.load?.();}}
$('#detail').addEventListener('close',()=>{pauseSongAudio();if(location.hash.startsWith('#musica/')&&$('#projection').hidden&&!$('#detail').open){replaceSimpleHash(SimpleUI.returnHash);render();document.querySelector('[data-action="song"][data-id="'+CSS.escape(SimpleUI.returnFocus||'')+'"]')?.focus();}});
refreshFavoriteView=function(){if($('#detail').open){detail();return;}if(['inicio','repertorio','playlist'].includes(page)){render();return;}updateCatalogue();};
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target)return;
 if(target.dataset.action==='audio-toggle'){const audio=$('#song-audio');if(audio){if(audio.paused)audio.play().catch(()=>$('#audio-status').textContent='Não foi possível reproduzir este áudio.');else audio.pause();}}
 if(target.dataset.action==='audio-seek-by'){const audio=$('#song-audio');if(audio&&Number.isFinite(audio.duration))audio.currentTime=Math.max(0,Math.min(audio.duration,audio.currentTime+Number(target.dataset.seconds)));}
 if(target.dataset.action==='simple-scope'){SimpleUI.scope=target.dataset.scope;replaceSimpleHash(SimpleUI.scope==='favorites'?'#favoritos':'#acervo');render();}
 if(target.dataset.action==='simple-clear-home'||target.dataset.action==='simple-clear-library'){filters.query='';const home=$('#home-search'),library=$('#global-search');if(home)home.value='';if(library)library.value='';if(page==='inicio'){updateHomeSearch();home?.focus();}else{updateCatalogue();library?.focus();}}
 if(target.dataset.action==='simple-add-song'&&isAdmin())edit('songs',null);
 if(target.dataset.action==='member-add-song'&&authenticatedUser?.role==='member')openMemberSongForm();
 if(target.dataset.action==='simple-clear'){SimpleUI.scope='all';replaceSimpleHash('#acervo');Object.assign(filters,{query:'',category:'',material:'',key:'',instrument:'',content:''});render();$('#global-search')?.focus();}
 if(target.dataset.action==='simple-manage-song'&&isAdmin()){$('#detail').close();replaceSimpleHash('#gerenciar');render();edit('songs',target.dataset.id);}
 if(target.dataset.action==='simple-upload'&&isAdmin()){
  let dialog=$('#simple-upload');if(!dialog){dialog=document.createElement('dialog');dialog.id='simple-upload';document.body.append(dialog);}
  dialog.innerHTML='<div class="dialog-head"><h2>Enviar arquivo</h2><button class="button secondary" data-close="simple-upload">Cancelar</button></div><form id="simple-upload-form" class="tab-content"><label>Tipo de material<select name="section">'+Object.entries(sections).map(([key,s])=>'<option value="'+key+'">'+esc(s.title)+'</option>').join('')+'</select></label><p>Na próxima etapa, informe o nome da música e escolha o arquivo.</p><button class="button" type="submit">Escolher arquivo</button></form>';dialog.showModal();
  $('#simple-upload-form').onsubmit=event=>{event.preventDefault();const selected=new FormData(event.target).get('section');if(!sections[selected])return;dialog.close();const previous=page;page=selected;addSongUpload();page=previous;};
 }
});
function openAudioManager(id){if(!isAdmin())return;const song=state.songs.find(item=>item.id===id);if(!song)return;const audio=audioForSong(song);let dialog=$('#resource-editor');if(!dialog){dialog=document.createElement('dialog');dialog.id='resource-editor';document.body.append(dialog);}dialog.innerHTML='<div class="dialog-head"><div><h2>Áudio da música</h2><p>'+esc(song.name)+'</p></div><button class="button secondary" data-close="resource-editor">Fechar</button></div><div class="tab-content"><div class="audio-admin-current">'+(audio?'<strong>'+esc(audio.label||'Áudio de referência')+'</strong><span>Arquivo associado</span>'+button('Remover áudio','audio-remove','data-song="'+esc(id)+'"',true,'close'):'<p>Nenhum áudio associado.</p>')+'</div><form id="audio-upload-form" class="account-form"><label>'+(audio?'Substituir arquivo de áudio':'Enviar arquivo de áudio')+'<input name="file" type="file" required accept=".mp3,.wav,.m4a,.ogg,.aac,.flac,audio/mpeg,audio/wav,audio/mp4,audio/ogg,audio/aac,audio/flac"></label><p class="form-hint">MP3, WAV, M4A, OGG, AAC ou FLAC · até 200 MB.</p><p id="audio-upload-status" role="status"></p><button class="button" type="submit">'+(audio?'Substituir áudio':'Enviar áudio')+'</button></form></div>';dialog.showModal();const form=$('#audio-upload-form');form.onsubmit=async event=>{event.preventDefault();if(!isAdmin())return;const file=new FormData(form).get('file'),status=$('#audio-upload-status'),submit=form.querySelector('button[type="submit"]');if(!file?.size)return;if(file.size>200*1024*1024){status.textContent='O limite é 200 MB.';return;}if(!/\.(mp3|wav|m4a|ogg|aac|flac)$/i.test(file.name)){status.textContent='Formato não permitido. Escolha MP3, WAV, M4A, OGG, AAC ou FLAC.';return;}submit.disabled=true;try{const info=await saveUploadedFile(file,value=>status.textContent='Enviando áudio… '+value+'%');const next=structuredClone(state),target=next.songs.find(item=>item.id===id);if(!target)throw Error('A música não existe mais.');const previous=audioForSong(target);target.resources=(target.resources||[]).filter(resource=>resource.type!=='audio');target.resources.push({id:audio?.id&&audio.id!=='audioLink'?audio.id:uid(),type:'audio',instrument:'Geral',label:file.name,...info});if(audio?.id==='audioLink')target.audioLink='';if(await persist(next)){if(previous?.storage==='server'&&previous.fileId)try{await api('/api/uploads/'+previous.fileId,{method:'DELETE'});}catch(error){console.warn('O arquivo anterior permaneceu no armazenamento:',error.message);}dialog.close();render();if($('#detail').open&&currentSong?.id===id){currentSong=state.songs.find(item=>item.id===id);detail();}toast('Áudio associado à música.');}else throw Error('Não foi possível salvar a associação do áudio.');}catch(error){status.textContent=error.message;toast(error.message);}finally{submit.disabled=false;}};}
editResources=openAudioManager;
document.addEventListener('click',async event=>{const target=event.target.closest('[data-action="audio-remove"]');if(!target||!isAdmin())return;const id=target.dataset.song;if(!confirm('Remover o áudio associado a esta música?'))return;const next=structuredClone(state),song=next.songs.find(item=>item.id===id),old=audioForSong(song);if(!song)return;song.resources=(song.resources||[]).filter(resource=>resource.type!=='audio');song.audioLink='';if(await persist(next)){render();if($('#resource-editor')?.open)$('#resource-editor').close();if($('#detail').open&&currentSong?.id===id){currentSong=state.songs.find(item=>item.id===id);detail();}if(old?.storage==='server'&&old.fileId){try{await api('/api/uploads/'+old.fileId,{method:'DELETE'});}catch(error){console.warn('Arquivo sem referência não foi removido do armazenamento:',error.message);}}toast('Áudio removido.');}});

